from svgpathtools import svg2paths
import numpy as np

# Load paths from SVG
paths, attributes = svg2paths('path_to_svg_with_mask')
path = paths[0]

# Sample N points along the path
N = 100
points = [path.point(t) for t in np.linspace(0, 1, N)]

# Convert to (x, y) tuples
polygon = [(int(p.real), int(p.imag)) for p in points]

#print(polygon)

polygon = np.array(polygon, np.int32)


